    {"새찬송가": "94", "통일찬송가": "94", "제목": "만복의 근원 하나님", "선정이유": "말할 수 없는 기쁨의 근원이신 하나님을 찬양한다"},
    {"새찬송가": "330", "통일찬송가": "243", "제목": "예수 사랑하심은", "선정이유": "보지 못하나 예수님을 사랑하는 신앙의 고백이다"}
