    {"대지": "서론", "내용": "모든 것에는 목적이 있다. 씨앗의 목적은 열매이고 여행의 목적은 도착이다. 믿음의 목적은 영혼의 구원이다. 베드로는 이 핵심 진리를 한 문장으로 선언한다", "예화_적용": "길고 험한 등산의 목적은 정상에 서는 것이다. 믿음의 모든 여정은 구원이라는 정상을 향해 올라가는 것이다"},
    {"대지": "1대지: 믿음의 여정 (과정)", "내용": "믿음은 순간적 결심이 아니라 지속적 여정이다. 시련과 기쁨, 사랑과 소망의 여정을 통해 믿음은 성장하고 성숙해진다", "예화_적용": "포도가 한순간에 익지 않듯 믿음도 시간과 과정을 통해 성숙해진다"},
    {"대지": "2대지: 믿음의 목적 (결국)", "내용": "텔로스는 단순한 끝이 아니라 목적과 완성이다. 믿음이 지향하는 최종 목적지는 영혼의 완전한 구원이다", "예화_적용": "항해의 목적은 항구에 도착하는 것이다. 믿음의 항해는 구원이라는 영원한 항구를 향해 나아간다"},
    {"대지": "3대지: 영혼의 구원 (완성)", "내용": "영혼의 구원은 전인격적 구원의 완성이다. 몸도 영혼도 전체가 구원받아 하나님의 영광 가운데 거하게 된다", "예화_적용": "나비가 되기 위해 번데기가 변형의 과정을 거치듯 영혼의 구원은 완전한 변화의 완성이다"},
    {"대지": "결론", "내용": "믿음의 결국은 영혼의 구원이다. 이 확신이 현재의 시련을 견디게 하고 보이지 않는 것을 사랑하게 하며 말할 수 없는 기쁨으로 기뻐하게 한다", "예화_적용": "결승선이 없는 달리기는 의미가 없다. 영혼의 구원이라는 결승선이 있기에 우리의 믿음의 달리기는 의미가 있다"}
