    {"항목": "쿰란 공동체의 성경 연구", "내용": "사해 사본으로 알려진 쿰란 공동체도 메시아적 예언을 열심히 연구했다. 이는 베드로 당시 유대 사회에서 메시아 예언에 대한 깊은 관심이 있었음을 보여준다", "목회적활용": "성경 연구의 전통은 오래되었다. 말씀을 연구하는 열정은 모든 시대 하나님의 백성의 특징이어야 한다"}
