    {"새찬송가": "364", "통일찬송가": "430", "제목": "주를 앙모하는 자", "선정이유": "순종하는 자녀로서 주님을 따르는 삶을 고백한다"},
    {"새찬송가": "446", "통일찬송가": "356", "제목": "내 주의 뜻대로 행하게", "선정이유": "사욕이 아닌 주님의 뜻에 순종하는 결의를 담고 있다"}
