  "표8_상담적용": [
    {"상황": "회심 전 습관에서 벗어나지 못하는 성도", "성경원리": "이전의 사욕은 무지의 시대의 것이다. 이제 하나님을 알았으니 과거의 습관에서 벗어나야 한다. 그러나 이 과정은 점진적이며 성령의 도움이 필요하다", "실제적용": "과거의 습관에서 벗어나지 못하는 것에 대해 정죄하기보다 성령의 능력을 의지하도록 안내하라. 구체적인 대안 행동을 함께 계획하고 책임 관계를 세우라"},
    {"상황": "세상의 가치관과 신앙의 가치관 사이에서 갈등하는 성도", "성경원리": "세상의 틀에 맞추는 것이 아니라 하나님의 뜻에 맞추는 것이 성도의 삶이다. 세상의 가치관이 편하게 느껴질 수 있으나 그것은 이전 무지의 삶으로 돌아가는 것이다", "실제적용": "세상의 가치관과 신앙의 가치관이 충돌하는 구체적인 상황을 함께 점검하라. 영원의 관점에서 올바른 선택을 할 수 있도록 성경적 원리를 적용하도록 도우라"}
  ],
  "표9_교차참조": [
    {"구절": "롬 12:2", "연결점": "이 세대를 본받지 말고 오직 마음을 새롭게 함으로 변화를 받아", "구분": "신약"},
    {"구절": "엡 4:22", "연결점": "유혹의 욕심을 따라 썩어져 가는 구습을 좇는 옛 사람을 벗어버리고", "구분": "신약"},
    {"구절": "갈 5:16", "연결점": "성령을 좇아 행하라 그리하면 육체의 욕심을 이루지 아니하리라", "구분": "신약"},
    {"구절": "행 17:30", "연결점": "알지 못하던 시대에는 하나님이 허물치 아니하셨거니와 이제는 어디든지 사람을 다 명하사 회개하라 하셨으니", "구분": "신약"},
    {"구절": "레 18:3", "연결점": "너희가 거하던 애굽 땅의 풍속을 좇지 말며 - 과거의 관습 버림", "구분": "구약"},
    {"구절": "엡 2:3", "연결점": "전에는 우리도 다 그 가운데서 우리 육체의 욕심을 따라 지내며", "구분": "신약"}
  ]
