    {"대지": "결론", "내용": "오늘 말씀을 향한 갈망이 식었다면, 처음 은혜받았을 때의 감격을 회복합시다. 갓난아이의 순수한 사모함으로 말씀 앞에 나아갑시다.", "예화_적용": "매일 말씀을 읽는 습관은 영적 생존의 문제입니다. 하루 세 끼를 먹듯 말씀도 규칙적으로 섭취해야 합니다."}
