    {"대지": "3대지: 그리하라의 명령 (체험에서 순종으로)", "내용": "'그리하라'는 앞절의 '말씀을 사모하라'를 가리킵니다. 은혜를 체험한 자는 당연히 말씀을 더 갈망하게 됩니다. 체험이 순종의 동기입니다.", "예화_적용": "좋은 의사에게 치료받은 환자가 그 의사의 처방을 더 신뢰하듯, 은혜를 체험한 자는 말씀에 더 순종합니다."},
    {"대지": "결론", "내용": "오늘 예배에서 주의 인자하심을 다시 맛봅시다. 그 맛이 우리를 말씀 사모로, 더 깊은 신앙의 세계로 이끌 것입니다.", "예화_적용": "매일의 경건 생활은 주의 인자하심을 맛보는 식탁입니다. 그 식탁에서 멀어지지 맙시다."}
