    {"영어원문": "They stumble at the word, being disobedient; and this was the appointment of God concerning them. God did not make them disobedient, but, foreseeing their disobedience, he determined the just punishment of it.", "한국어번역": "그들은 불순종하여 말씀에 걸려 넘어지니, 이것이 그들에 관한 하나님의 작정이었습니다. 하나님이 그들을 불순종하게 만드신 것이 아니라 그들의 불순종을 미리 아시고 그에 대한 공의로운 형벌을 정하신 것입니다.", "핵심통찰": "하나님의 예정은 불순종의 원인이 아니라 불순종에 대한 공의로운 결과입니다."}
