    {"항목": "어두움에서 빛으로의 전환", "내용": "이방인들은 종교적으로 우상 숭배의 어두움 속에 있었고, 유대인 산 사이에서도 그리스도를 알기 전의 상태는 영적 어두움이었습니다. 복음은 이 어두움에서 빛으로의 전환을 가져옵니다.", "목회적활용": "회심 전과 후의 극적인 변화를 상기시켜 감사와 헌신의 동기를 부여합니다."}
