    {"대지": "서론", "내용": "정체성은 사명을 결정합니다. 군인은 나라를 지키고, 의사는 환자를 치료합니다. 교회의 정체성을 알면 교회의 사명을 알게 됩니다.", "예화_적용": "여권은 내가 어느 나라 국민인지를 증명합니다. 베드로는 성도에게 영적 여권을 발급하며 네 가지 정체성을 선언합니다."},
    {"대지": "1대지: 택하신 족속 (선택의 은혜)", "내용": "우리가 하나님을 선택한 것이 아니라 하나님이 우리를 택하셨습니다. 이 선택은 공로에 근거한 것이 아니라 순전한 은혜입니다.", "예화_적용": "입양된 아이가 부모를 선택한 것이 아니듯, 우리도 하나님의 주권적 사랑으로 택함받았습니다."},
    {"대지": "2대지: 왕같은 제사장 (이중적 사명)", "내용": "왕의 권위로 세상을 다스리고 제사장의 거룩함으로 하나님을 섬깁니다. 세상 속에서 왕의 위엄을 지키며 하나님 앞에서 제사장의 겸손을 가집니다.", "예화_적용": "왕관과 제사장 관을 동시에 쓴 멜기세덱처럼, 그리스도인은 세상에서의 책임과 하나님 앞에서의 헌신을 함께 감당합니다."},
    {"대지": "3대지: 덕을 선전하라 (선교적 사명)", "내용": "교회의 궁극적 목적은 하나님의 아름다운 덕을 세상에 선전하는 것입니다. 어두움에서 빛으로 인도하신 은혜를 세상에 증거합니다.", "예화_적용": "등대가 자기를 위해 빛을 비추지 않고 항해하는 배를 위해 빛을 비추듯, 우리도 세상을 위해 하나님의 빛을 비춰야 합니다."},
    {"대지": "결론", "내용": "택하신 족속이요 왕같은 제사장인 우리, 이 위대한 정체성에 걸맞은 삶을 살아갑시다. 하나님의 덕을 온 세상에 선전합시다.", "예화_적용": "나는 택함받은 자입니다. 나는 왕같은 제사장입니다. 이 고백이 오늘의 삶을 변화시킵니다."}
