    {"교리": "이방인의 포함", "설명": "원래 이스라엘에게 주어진 약속이 이방인 성도에게까지 확대됩니다. 이는 하나님의 구원 계획이 한 민족에 국한되지 않고 모든 민족을 포괄함을 보여줍니다.", "관련구절": "롬 9:24-26, 갈 3:28-29, 엡 2:12-13"}
