    {"원어": "ἀπέχω (아페코)", "의미_문법": "떨어져 있다, 제어하다, 삼가다 - 현재 중간태 부정사", "설교포인트": "아페코는 '거리를 두다'라는 뜻으로, 정욕과의 적극적 분리를 명합니다. 타협이나 관망이 아니라 단호한 거리두기입니다."}
