    {"대지": "서론", "내용": "말보다 행동이 더 크게 말합니다. 아무리 좋은 말을 해도 삶이 따르지 않으면 설득력이 없습니다. 베드로는 박해 속에서 선한 행실로 복음을 증거하라고 권합니다.", "예화_적용": "한 권의 설교집보다 한 사람의 거룩한 삶이 더 많은 사람을 변화시킵니다."},
    {"대지": "1대지: 이방인 중에서의 삶 (세상 속의 교회)", "내용": "성도는 세상에서 분리된 존재가 아니라 세상 속에서 빛을 발하는 존재입니다. 도피가 아니라 침투가 우리의 사명입니다.", "예화_적용": "소금이 음식 밖에 있으면 무용합니다. 음식 속에 들어가야 맛을 냅니다."},
    {"대지": "2대지: 비방을 이기는 선행 (삶의 증거)", "내용": "비방하는 자들이 선한 행실을 지켜보고 있습니다. 우리의 삶이 비방의 근거가 될 수도, 비방을 잠재울 수도 있습니다.", "예화_적용": "법정에서 가장 강력한 증거는 목격자의 증언입니다. 우리의 삶이 복음의 목격 증거입니다."},
    {"대지": "3대지: 하나님께 영광을 돌림 (궁극적 목표)", "내용": "선한 행실의 최종 목표는 자기 칭찬이 아니라 하나님께 영광을 돌리는 것입니다. 비방자들도 하나님의 방문의 날에 영광을 돌리게 됩니다.", "예화_적용": "좋은 작품을 보면 작가를 칭찬하듯, 성도의 선한 삶을 보면 하나님께 영광을 돌리게 됩니다."},
    {"대지": "결론", "내용": "오늘 우리의 행실이 비방자들에게 어떤 메시지를 보내고 있습니까? 삶으로 복음을 전합시다.", "예화_적용": "내일 직장에서, 이웃과의 관계에서 선한 행실이 가장 강력한 전도입니다."}
