    {"상황": "원한과 복수심으로 괴로운 분", "성경원리": "그리스도는 욕을 받으시되 욕하지 않으시고 공의의 심판자에게 맡기셨습니다. 보복은 하나님의 영역이며, 우리는 맡기는 것이 최선입니다.", "실제적용": "원한의 감정을 억누르지 말고 하나님께 솔직히 표현하도록 도우며(시편의 저주 시편 활용), 보복 대신 용서를 선택하는 과정을 함께 걸어갑니다. 용서가 감정이 아닌 의지의 결단임을 가르칩니다."}
