    {"구절": "시 23:1-3", "연결점": "여호와는 나의 목자시니 내가 부족함이 없으리로다 그가 나를 푸른 초장에 누이시며 쉴 만한 물가으로 인도하시는도다", "구분": "구약"},
    {"구절": "히 13:20", "연결점": "양의 큰 목자이신 우리 주 예수를 영원한 언약의 피로 죽은 자 가운데서 이끌어 내신 평강의 하나님이", "구분": "신약"}
