    {"항목": "가부장적 사회구조", "내용": "1세기 로마 사회는 철저한 가부장제였습니다. 아내의 종교적 독립은 사회적으로 용납되지 않았으나, 베드로는 이 구조 안에서 신앙의 영향력을 발휘하도록 지혜를 제시합니다.", "목회적활용": "사회적 구조를 무시하지 않으면서도 그 안에서 변혁적 영향력을 미치는 지혜를 가르칩니다."}
