    {"대지": "서론", "내용": "유행은 시대마다 바뀌지만, 거룩한 부녀들의 단장법은 세월이 지나도 변하지 않습니다. 하나님께 소망을 두고 순복으로 단장하는 것입니다.", "예화_적용": "클래식 의상은 유행을 타지 않듯, 내면의 아름다움은 시대를 초월합니다."},
    {"대지": "1대지: 하나님께 소망을 둠 (단장의 기초)", "내용": "거룩한 부녀들의 순복은 하나님에 대한 소망에 근거했습니다. 미래를 하나님께 맡겼기에 현재를 겸손히 살 수 있었습니다.", "예화_적용": "넘어져도 다시 일으켜 주실 분이 계시기에 담대히 걸어갈 수 있습니다."},
    {"대지": "2대지: 순복의 단장 (내면의 치장)", "내용": "이 부녀들은 금이나 보석이 아니라 순복과 온유로 자신을 단장했습니다. 이것이 시대를 초월한 아름다움입니다.", "예화_적용": "사라, 한나, 룻의 이름이 수천 년이 지난 오늘까지 기억되는 것은 외모 때문이 아니라 신앙 때문입니다."},
    {"대지": "3대지: 오늘의 적용 (변치 않는 원리)", "내용": "시대가 바뀌어도 이 원리는 변하지 않습니다. 하나님께 소망을 두고 관계 안에서 겸손하게 사는 것이 참된 아름다움입니다.", "예화_적용": "현대의 거룩한 부녀가 되기를 선택합시다."},
    {"대지": "결론", "내용": "구약의 거룩한 부녀들처럼 하나님께 소망을 두고, 순복으로 자신을 단장하는 삶을 살아갑시다.", "예화_적용": "오늘의 믿음이 내일의 증거가 됩니다."}
