    {"원어": "τέκνον (테크논)", "의미_문법": "자녀, 딸 - 중성 명사 복수", "설교포인트": "사라의 딸이 된다는 것은 혈통이 아닌 신앙적 계승을 의미합니다. 사라의 믿음과 순복을 따르는 자가 사라의 영적 후손입니다."},
    {"원어": "πτόησις (프토에시스)", "의미_문법": "두려움, 놀람 - 여성 명사 단수", "설교포인트": "프토에시스는 갑작스러운 공포를 가리킵니다. 선을 행하면서 어떤 두려움에도 놀라지 않는 담대함이 사라의 딸의 표시입니다."}
