    {"대지": "서론", "내용": "세례는 물에 들어갔다 나오는 단순한 의식이 아닙니다. 그것은 선한 양심으로 하나님께 드리는 서약이며, 그리스도의 부활에 참여하는 것입니다.", "예화_적용": "결혼 반지가 사랑의 실체가 아닌 것처럼, 세례의 물이 구원의 실체가 아닙니다. 반지 뒤의 사랑처럼, 세례 뒤의 믿음이 핵심입니다."},
    {"대지": "1대지: 노아의 물과 세례의 물 (예표와 성취)", "내용": "홍수의 물이 노아를 구원했듯이, 세례의 물이 우리의 구원을 표시합니다. 물은 심판과 구원의 이중 의미를 가집니다.", "예화_적용": "수술은 아프지만 치유를 위한 것이듯, 물의 심판은 구원을 위한 것이었습니다."},
    {"대지": "2대지: 육체가 아닌 양심 (내적 의미)", "내용": "세례는 몸을 씻는 것이 아니라 양심을 하나님께 향하게 하는 것입니다. 외적 의식이 아닌 내적 결단이 핵심입니다.", "예화_적용": "세차를 아무리 해도 엔진이 고장나면 차가 가지 않듯, 외적 의식만으로는 영적 변화가 일어나지 않습니다."},
    {"대지": "3대지: 부활의 능력 (세례의 근거)", "내용": "세례의 효력은 예수 그리스도의 부활에 근거합니다. 부활이 없다면 세례도 무의미합니다.", "예화_적용": "전기가 없으면 전구가 빛을 낼 수 없듯, 부활의 능력이 없으면 세례도 생명을 줄 수 없습니다."},
    {"대지": "결론", "내용": "세례의 참된 의미를 기억합시다. 그것은 그리스도의 부활에 근거한 선한 양심의 서약입니다.", "예화_적용": "자신의 세례를 기억하며, 그날의 서약을 새롭게 합시다."}
