    {"구절": "빌 3:13-14", "연결점": "뒤에 있는 것은 잊어버리고 앞에 있는 것을 잡으려고 푯대를 향하여 그리스도 예수 안에서 하나님이 위에서 부르신 부름의 상을 위하여 쫓아가노라", "구분": "신약"}
