    {"원어": "βλασφημέω (블라스페메오)", "의미_문법": "비방하다, 모독하다 - 현재 능동 분사", "설교포인트": "블라스페메오는 악한 말로 공격하는 것입니다. 세상은 그리스도인의 거룩한 삶을 비방하지만, 이는 오히려 신앙의 증거입니다."}
