    {"교리": "사랑의 덮는 능력", "설명": "사랑은 허다한 죄를 덮습니다. 이것은 죄를 묵인하는 것이 아니라, 남의 허물을 용서하고 회복을 돕는 것입니다. 하나님이 우리의 죄를 사랑으로 덮으셨듯이.", "관련구절": "잠 10:12, 약 5:20, 시 32:1"}
