    {"대지": "3대지: 허다한 죄를 덮음 (사랑의 능력)", "내용": "사랑은 남의 허물을 폭로하지 않고 덮어줍니다. 용서하고, 회복을 돕고, 다시 기회를 줍니다.", "예화_적용": "어머니의 사랑이 자녀의 허물을 덮어주듯, 하나님의 사랑은 우리의 허다한 죄를 덮어주셨습니다."},
    {"대지": "결론", "내용": "오늘 우리가 먼저 사랑합시다. 남의 허물을 덮어주는 사랑을 실천합시다. 이것이 교회를 세우는 가장 강력한 힘입니다.", "예화_적용": "교회의 문제는 프로그램이 아닌 사랑으로 해결됩니다."}
