    {"대지": "2대지: 하나님의 힘으로 (봉사하는 은사)", "내용": "봉사는 자기 능력이 아닌 하나님이 공급하시는 힘으로 해야 합니다. 이것이 번아웃을 방지하고 겸손을 유지하게 합니다.", "예화_적용": "전기차가 배터리를 충전해야 달리듯, 봉사자도 하나님의 힘을 공급받아야 지속적으로 봉사할 수 있습니다."},
    {"대지": "3대지: 하나님의 영광을 위해 (최종 목적)", "내용": "모든 은사 사용의 최종 목적은 하나님의 영광입니다. 이 목적을 잃으면 은사가 도구가 아닌 우상이 됩니다.", "예화_적용": "강물이 바다로 흘러가듯, 모든 은사의 열매는 하나님의 영광이라는 바다로 흘러가야 합니다."},
    {"대지": "결론", "내용": "오늘 나의 말과 행위가 하나님의 영광을 위한 것인지 점검합시다. '아멘'으로 화답하며, 하나님의 영광과 권능이 영원함을 고백합시다.", "예화_적용": "영광과 권능이 세세에 무궁토록 하나님께 있습니다. 아멘!"}
