    {"대지": "2대지: 부끄러워 말라 (당당한 고백)", "내용": "그리스도인이라는 정체성을 숨기지 말아야 합니다. 바울도 '내가 복음을 부끄러워하지 아니하노니'(롬 1:16)라고 했습니다.", "예화_적용": "군인이 군복을 부끄러워하지 않듯, 그리스도인도 자신의 정체성을 부끄러워하지 말아야 합니다."},
    {"대지": "3대지: 하나님께 영광을 (고난 속의 찬양)", "내용": "고난을 참는 것을 넘어 그 안에서 하나님께 영광을 돌리라는 적극적 명령입니다.", "예화_적용": "바울과 실라는 감옥에서 찬양했습니다(행 16:25). 고난 속의 찬양이 가장 아름다운 찬양입니다."},
    {"대지": "결론", "내용": "그리스도인이라는 이름을 부끄러워하지 맙시다. 이 이름으로 고난받을 때 하나님께 영광을 돌립시다.", "예화_적용": "우리가 당하는 모든 고난이 하나님의 영광을 나타내는 기회가 되기를 원합니다."}
