    {"원어": "οἶκος (오이코스)", "의미_문법": "집, 가족 - 남성 명사 단수 속격", "설교포인트": "오이코스는 여기서 교회를 가리킵니다. 하나님의 집은 성전이자 교회이며 성도의 공동체입니다."},
    {"원어": "ἄρχω (아르코)", "의미_문법": "시작하다 - 아오리스트 부정사", "설교포인트": "심판이 하나님의 집에서 '시작'된다는 것은 교회가 면제되는 것이 아니라 가장 먼저 심판의 대상이 됨을 의미합니다."},
    {"원어": "ἀπειθέω (아페이데오)", "의미_문법": "순종하지 않다 - 현재 능동 분사", "설교포인트": "아페이데오는 복음을 듣고도 순종하지 않는 것입니다. 교회도 심판을 받는데, 복음을 거부한 자들의 마지막은 얼마나 더 두려울까요."}
