    {"대지": "서론", "내용": "베드로전서 4장의 마지막 절은 고난에 대한 최종 결론입니다. 고난 중에 할 일은 두 가지: 선을 행하고, 영혼을 하나님께 맡기는 것입니다.", "예화_적용": "비행기가 난기류를 만났을 때, 승객이 할 일은 안전벨트를 매고 조종사를 신뢰하는 것입니다. 우리의 조종사는 미쁘신 조물주입니다."},
    {"대지": "1대지: 하나님의 뜻대로 고난 (고난의 의미)", "내용": "모든 고난이 아닌, 하나님의 뜻대로 받는 고난이 여기서 말하는 고난입니다. 15절의 범죄로 인한 고난과 구별됩니다.", "예화_적용": "수술의 아픔은 의사의 뜻대로 받는 것이기에 치유를 위한 것입니다. 자해의 아픔과는 본질적으로 다릅니다."},
    {"대지": "2대지: 선을 행하는 중에 (고난 중의 선행)", "내용": "고난이 선행을 멈추는 이유가 되어서는 안 됩니다. 오히려 고난 중에 선을 행하는 것이 가장 아름다운 증거입니다.", "예화_적용": "감옥에서도 편지를 쓰며 교회를 세운 바울처럼, 어떤 상황에서도 선을 행할 수 있습니다."},
    {"대지": "3대지: 미쁘신 조물주께 부탁 (궁극적 신뢰)", "내용": "미쁘신(신실한) 조물주(창조주)께 영혼을 맡기는 것은 최고의 신앙 고백입니다. 만드신 분이 가장 잘 지키십니다.", "예화_적용": "예수님이 십자가에서 '아버지여 내 영혼을 아버지 손에 부탁하나이다'라고 하신 것이 우리의 모범입니다."},
    {"대지": "결론", "내용": "오늘 우리의 영혼을 미쁘신 조물주께 맡깁시다. 고난 중에도 선을 행하며, 신실하신 하나님을 신뢰합시다. 그분은 맡긴 것을 반드시 지키시는 분입니다.", "예화_적용": "인생의 마지막 순간에도 '내 영혼을 주님 손에 부탁합니다'라고 고백할 수 있기를 원합니다."}
