    {"교리": "고난의 증인과 영광의 참여자", "설명": "고난을 목격하고 경험한 자만이 영광에 참여합니다. 고난과 영광은 분리될 수 없으며, 베드로는 이 두 가지 모두의 동반자입니다.", "관련구절": "롬 8:17, 벧전 4:13, 딤후 2:11-12"}
