    {"원어": "ἐγκομβόομαι (엥콤보오마이)", "의미_문법": "허리를 동이다, 입다 - 아오리스트 중간태 명령법", "설교포인트": "엥콤보오마이는 종이 앞치마를 매는 것에서 유래했습니다. 겸손을 앞치마처럼 매라는 것은 섬김의 자세를 취하라는 뜻입니다. 예수님이 수건을 허리에 두르시고 제자들의 발을 씻기신 장면(요 13:4-5)을 연상시킵니다."},
    {"원어": "ὑπερήφανος (휘페레파노스)", "의미_문법": "교만한 - 형용사", "설교포인트": "휘페레파노스는 '위로(휘페르) 나타나는(파이노)'으로, 자기를 남보다 높이 드러내는 자입니다. 하나님이 대적하시는 대상입니다."}
