    {"대지": "2대지: 깨어라 (경계 태세)", "내용": "그레고레오는 보초를 서듯 경계하는 것입니다. 잠드는 순간이 공격의 순간입니다.", "예화_적용": "전쟁에서 보초병이 졸면 적이 침투합니다. 영적 보초병인 우리도 졸면 안 됩니다."},
    {"대지": "3대지: 우는 사자 마귀 (적의 정체)", "내용": "마귀는 우는 사자같이 두루 다니며 삼킬 자를 찾습니다. 그의 목적은 파멸이며, 항상 활동합니다.", "예화_적용": "그러나 마귀는 유다 사자보다 약합니다. '너희 속에 계신 이가 세상에 있는 자보다 크심이라'(요일 4:4)."},
    {"대지": "결론", "내용": "근신하고 깨어 있읍시다. 우는 사자가 우리 주변을 배회하고 있습니다. 그러나 두려워하지 마십시오. 우리의 사자이신 그리스도가 더 강하십니다.", "예화_적용": "깨어 기도하는 것이 마귀를 이기는 가장 강력한 무기입니다."}
