    {"교리": "고난의 보편성과 연대", "설명": "고난은 특정 개인이나 교회만의 것이 아닙니다. 전 세계 형제들이 동일한 고난을 당하고 있습니다. 이 인식은 고립감을 깨고 연대 의식을 형성합니다.", "관련구절": "고전 10:13, 히 13:3, 계 1:9"}
