    {"대지": "서론", "내용": "전쟁터에서 혼자라고 생각하면 공포에 빠지지만, 전우가 있다는 것을 알면 용기가 납니다. 베드로는 '너만 이 싸움을 하는 것이 아니다'라고 위로합니다.", "예화_적용": "등산할 때 앞서 간 사람의 발자국을 보면 용기가 나듯, 같은 길을 걷는 형제들이 있다는 것이 힘이 됩니다."},
    {"대지": "1대지: 대적하라 (도망가지 말라)", "내용": "안티스테미는 맞서 서라는 명령입니다. 마귀에게 도망가면 더 쫓아옵니다. 맞서면 도망가는 것은 마귀입니다(약 4:7).", "예화_적용": "개에게 쫓기면 도망가지 말고 서라는 말이 있듯, 마귀에게도 믿음으로 맞서면 물러갑니다."},
    {"대지": "2대지: 믿음을 굳게 (영적 무기)", "내용": "스테레오스(견고한) 믿음이 마귀를 이기는 무기입니다. 흔들리는 믿음은 방패가 되지 못합니다.", "예화_적용": "성벽이 견고해야 적의 공격을 막듯, 믿음이 견고해야 마귀의 공격을 막을 수 있습니다."},
    {"대지": "3대지: 너희 형제들도 (고난의 연대)", "내용": "전 세계 형제들이 동일한 고난을 당하고 있습니다. 나만의 싸움이 아닙니다. 이 연대 의식이 힘을 줍니다.", "예화_적용": "전 세계에서 같은 시간에 기도하는 그리스도인들이 있다는 사실이 우리에게 힘을 줍니다."},
    {"대지": "결론", "내용": "믿음으로 마귀를 대적합시다. 혼자가 아닙니다. 전 세계 형제들이 같은 싸움을 싸우고 있습니다.", "예화_적용": "우리는 하나님의 군대입니다. 함께 싸우면 반드시 이깁니다."}
