    {"대지": "서론", "내용": "베드로전서의 모든 고난의 가르침이 이 짧은 송영으로 귀결됩니다. 모든 것의 결론은 하나님의 영원한 권능입니다.", "예화_적용": "교향곡의 마지막 음이 모든 악장을 하나로 묶듯, 이 송영이 전체 서신을 하나로 묶습니다."},
    {"대지": "1대지: 권력이 (하나님의 능력)", "내용": "크라토스(권력)는 압도적 능력입니다. 마귀의 권세보다, 세상의 권력보다 하나님의 크라토스가 더 큽니다.", "예화_적용": "아무리 큰 파도도 바다의 깊이를 바꾸지 못하듯, 어떤 시련도 하나님의 권능을 흔들지 못합니다."},
    {"대지": "2대지: 세세무궁토록 (영원한 통치)", "내용": "하나님의 권능은 시간의 제약을 받지 않습니다. 과거에도 현재에도 미래에도 영원히 통치하십니다.", "예화_적용": "왕조는 흥하고 망하지만, 하나님의 나라는 영원합니다."},
    {"대지": "3대지: 아멘 (공동체의 고백)", "내용": "아멘은 혼자가 아닌 공동체의 고백입니다. 함께 '아멘'이라고 선언할 때 믿음이 강해집니다.", "예화_적용": "독창도 아름답지만, 합창의 아멘이 더 웅장합니다."},
    {"대지": "결론", "내용": "고난의 한가운데서도 선포합니다. 권력이 세세무궁토록 하나님께 있습니다. 아멘!", "예화_적용": "이 아멘이 우리의 모든 두려움과 염려에 대한 최종 답입니다."}
